def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:  # 本轮无交换，已有序，提前退出
            break
    return arr
# 边界：空列表/单元素天然有序；时间复杂度O(n^2)，教学用，生产建议用内置sorted()（Timsort）

